random.seed(11)
found=0
for trial in range(400):
    N=random.choice([2,3])
    K=random.choice([3,4])
    H=[[random.uniform(2,10) for _ in range(N)] for _ in range(K)]
    W=[[random.uniform(0.1,2.5) for _ in range(N)] for _ in range(K)]
    options=[[(0.,0.)]+[(random.uniform(0.5,5),random.uniform(0.5,4)) for _ in range(random.choice([1,2,3]))] for _ in range(N)]
    nL=random.choice([2,3])
    weight_sets=[[random.uniform(0.1,2) for _ in range(K)] for _ in range(nL)]
    B=random.choice([4,5,6]); Z=random.choice([4,5,6])
    budgets=sorted(random.sample([x/2 for x in range(0,16)],B))
    zs=sorted(random.sample([0.5,0.8,1.0,1.28,1.5,1.96,2.0,2.58,3.0,3.5],Z))
