        L=h.robust_policy_lineage(H,W,thresholds,quantiles,policies,options,budgets,weight_sets,zs)
    except ValueError:
        continue
    kinds=set()
    for ax in ("budget","z"):
        for pair in L["axes"][ax]["transitions"]:
            for ev in pair: kinds.add(ev[0])
