            for pi,pair in enumerate(L["axes"][ax]["transitions"]):
                for k,fr,to,ov in pair:
                    if k in ("split","merge","merge_split"):
                        exp.append([ax,[pi,pi+1],k,fr,to,ov])
        assert J["branches"]==exp, ("mismatch", trial)
        json.dumps(J)
        found+=1
        if found<=3:
            print("trial",trial,sorted(kinds))
            for b in J["branches"][:6]: print(" ",b[0],b[1],b[2],"from",b[3],"to",b[4],"ov",b[5])
        if found>=8: break
print("verified datasets:",found)
